// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, random } from '../remotionShim';


export type PaperSynthesisProps = Record<string, any>;

const SynthesisElement: React.FC<{
  baseStyle: React.CSSProperties;
  glowProgress: number;
  primary: string;
  secondary: string;
  filled?: boolean;
}> = ({ baseStyle, glowProgress, primary, secondary, filled = false }) => {
  return (
    <div style={{ position: "absolute", ...baseStyle, transition: "none" }}>
      {/* Base Structural State */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundColor: secondary,
          borderRadius: baseStyle.borderRadius,
          opacity: 1 - glowProgress,
          transition: "none",
        }}
      />
      {/* Glowing Focal State */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          border: filled ? "none" : `2px solid ${primary}`,
          backgroundColor: filled ? primary : "#FFFFFF",
          opacity: glowProgress,
          borderRadius: baseStyle.borderRadius,
          boxShadow: glowProgress > 0 ? `0 0 ${20 * glowProgress}px ${primary}4D` : "none",
          transition: "none",
        }}
      />
    </div>
  );
};

const DenseContent: React.FC<{ opacity: number; textureColor: string }> = ({ opacity, textureColor }) => {
  const shapes = [
    { w: "80%", h: "1.5%", top: "5%" },
    { w: "90%", h: "1.5%", top: "10%" },
    { w: "60%", h: "1.5%", top: "15%" },
    
    { w: "18%", h: "14%", top: "25%", left: "0%" },
    { w: "18%", h: "18%", top: "21%", left: "22%" },
    { w: "18%", h: "10%", top: "29%", left: "44%" },
    { w: "18%", h: "22%", top: "17%", left: "66%" },
    
    { w: "85%", h: "1.5%", top: "45%" },
    { w: "95%", h: "1.5%", top: "50%" },
    { w: "70%", h: "1.5%", top: "55%" },
    { w: "40%", h: "1.5%", top: "60%" },
    
    { w: "45%", h: "8%", top: "68%", left: "0%" },
    { w: "45%", h: "8%", top: "68%", left: "55%" },
    
    { w: "80%", h: "1.5%", top: "82%" },
    { w: "60%", h: "1.5%", top: "87%" },
    { w: "90%", h: "1.5%", top: "92%" },
    { w: "50%", h: "1.5%", top: "97%" },
  ];

  return (
    <div style={{ position: "absolute", inset: "10%", opacity, transition: "none" }}>
      {shapes.map((s, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            top: s.top,
            left: s.left || 0,
            width: s.w,
            height: s.h,
            backgroundColor: textureColor,
            borderRadius: 2,
            transition: "none",
          }}
        />
      ))}
    </div>
  );
};

const PaperSynthesis: React.FC<PaperSynthesisProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = true,
  durationInSeconds = 6,
  primaryColor = "#0077C5",
  secondaryColor = "#E0E0E0",
  textureColor = "#D5D5D5",
  pageCount = 25,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const sweepStart = 2 * fps;
  const sweepDuration = 3 * fps;

  const synthesisStart = 3.5 * fps;
  const synthesisDuration = 1 * fps;
  
  const glowStart = 4.5 * fps;
  const glowDuration = 0.5 * fps;

  const sweepProgress = interpolate(frame, [sweepStart, sweepStart + sweepDuration], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const synthesisProgress = interpolate(frame, [synthesisStart, synthesisStart + synthesisDuration], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const glowProgress = interpolate(frame, [glowStart, glowStart + glowDuration], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const pageWidth = width * 0.3;
  const pageHeight = height * 0.75;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {Array.from({ length: pageCount }).map((_, i) => {
        const isTopPage = i === pageCount - 1;

        const startX = interpolate(random(`x-${i}`), [0, 1], [width * 0.05, width * 0.95]);
        const startY = interpolate(random(`y-${i}`), [0, 1], [height * 0.05, height * 0.95]);
        const startRot = interpolate(random(`rot-${i}`), [0, 1], [-20, 20]);

        const targetX = width / 2;
        const targetY = height / 2;
        const targetRot = 0;

        const currentX = interpolate(sweepProgress, [0, 1], [startX, targetX]);
        const currentY = interpolate(sweepProgress, [0, 1], [startY, targetY]);
        const currentRot = interpolate(sweepProgress, [0, 1], [startRot, targetRot]);

        const pageOpacity = isTopPage
          ? 1
          : interpolate(sweepProgress, [0.8, 1], [1, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

        if (pageOpacity <= 0 && !isTopPage) return null;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: pageWidth,
              height: pageHeight,
              backgroundColor: "#FFFFFF",
              border: `1px solid ${textureColor}33`,
              boxShadow: "0 12px 30px rgba(0,0,0,0.08)",
              borderRadius: 4,
              transform: `translate(${currentX}px, ${currentY}px) translate(-50%, -50%) rotate(${currentRot}deg)`,
              opacity: pageOpacity,
              transition: "none",
              overflow: "hidden",
            }}
          >
            <DenseContent opacity={isTopPage ? 1 - synthesisProgress : 1} textureColor={textureColor} />

            {isTopPage && (
              <div
                style={{
                  position: "absolute",
                  inset: "10%",
                  opacity: synthesisProgress,
                  transition: "none",
                }}
              >
                {/* 1. Bold Horizontal Headline Marker */}
                <SynthesisElement
                  baseStyle={{ top: "0%", left: "0%", width: "65%", height: "8%", borderRadius: 6 }}
                  glowProgress={glowProgress}
                  primary={primaryColor}
                  secondary={secondaryColor}
                  filled={true}
                />

                {/* 2. Large Featured Number Marker */}
                <SynthesisElement
                  baseStyle={{ top: "20%", left: "0%", width: "40%", height: "30%", borderRadius: 12 }}
                  glowProgress={glowProgress}
                  primary={primaryColor}
                  secondary={secondaryColor}
                  filled={true}
                />

                {/* 3. Bar Chart */}
                <div
                  style={{
                    position: "absolute",
                    top: "20%",
                    left: "50%",
                    width: "50%",
                    height: "30%",
                    display: "flex",
                    alignItems: "flex-end",
                    justifyContent: "space-between",
                    transition: "none",
                  }}
                >
                  {[0.4, 0.7, 0.5, 0.9, 0.6, 1.0].map((h, idx) => (
                    <SynthesisElement
                      key={idx}
                      baseStyle={{
                        position: "relative",
                        width: "12%",
                        height: `${h * 100}%`,
                        borderRadius: "4px 4px 0 0",
                      }}
                      glowProgress={glowProgress}
                      primary={primaryColor}
                      secondary={secondaryColor}
                      filled={true}
                    />
                  ))}
                </div>

                {/* Structural lower lines for balance (mimicking text lines) */}
                {[
                  { top: "60%", width: "90%" },
                  { top: "68%", width: "60%" },
                  { top: "76%", width: "85%" },
                  { top: "84%", width: "70%" },
                  { top: "92%", width: "50%" },
                ].map((line, idx) => (
                  <SynthesisElement
                    key={idx}
                    baseStyle={{
                      top: line.top,
                      left: "0%",
                      width: line.width,
                      height: "2.5%",
                      borderRadius: 4,
                    }}
                    glowProgress={glowProgress}
                    primary={primaryColor}
                    secondary={secondaryColor}
                    filled={true}
                  />
                ))}
              </div>
            )}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default PaperSynthesis;